import{_ as t,o as s,c as n,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const g=JSON.parse('{"title":"坐忘论·全书引读","description":"坐忘论的整体地图：结构、思想来源、与《天隐子》的对应、路线图与常见误读。","frontmatter":{"title":"坐忘论·全书引读","description":"坐忘论的整体地图：结构、思想来源、与《天隐子》的对应、路线图与常见误读。","category":"guide","aliases":["坐忘论引读","坐忘论导读","坐忘论学习"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/guide.md","filePath":"daoism/daoist-classics/zuowang-lun/guide.md","lastUpdated":1789714390000}'),l={name:"daoism/daoist-classics/zuowang-lun/guide.md"};function i(o,a,p,r,d,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="坐忘论·全书引读" tabindex="-1">坐忘论·全书引读 <a class="header-anchor" href="#坐忘论·全书引读" aria-label="Permalink to &quot;坐忘论·全书引读&quot;">​</a></h1><p>本篇是《坐忘论》的全局地图，不逐句解释。三张地图：<strong>结构地图</strong>（七篇各自解决什么问题）、<strong>来源地图</strong>（主要引自哪些经典）、<strong>对应地图</strong>（与《天隐子》如何互为表里）。引文出处的逐条考订另见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h2 id="一、这是一部什么样的书" tabindex="-1">一、这是一部什么样的书 <a class="header-anchor" href="#一、这是一部什么样的书" aria-label="Permalink to &quot;一、这是一部什么样的书&quot;">​</a></h2><p>《坐忘论》传统上题为唐代司马承祯所撰。司马承祯，字子微，法号道隐，自号白云子，是唐代上清派的重要道士。</p><p>「坐忘」一词出自《庄子·大宗师》。颜回说：</p><blockquote><p>堕肢体，黜聪明，离形去知，同于大通，此谓坐忘。</p></blockquote><p>它描述的是：放下对形体的执著；放下以聪明智虑为中心的分别；超越「我」与「物」的对立；最终与大道冥合。</p><p>但《庄子》主要描述坐忘的<strong>境界</strong>，并未详说普通人如何一步步到达。《坐忘论》的重要贡献，正是把它整理成一条可以渐次修习的道路：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>敬信 → 断缘 → 收心 → 简事 → 真观 → 泰定 → 得道</span></span></code></pre></div><p>所以它并不从盘坐姿势开始，而是从一场<strong>价值反省</strong>开始——先追问：我们口头上珍惜生命，实际生活却是否一直在耗损生命？它真正回答的是：</p><blockquote><p><strong>一个仍然生活在事务、欲望、情绪和分别之中的人，怎样逐步减少外在牵累，收摄内心，生起真观，进入定慧，最后与道冥合？</strong></p></blockquote><h2 id="二、为什么以「坐忘」为名-却分为七篇" tabindex="-1">二、为什么以「坐忘」为名，却分为七篇 <a class="header-anchor" href="#二、为什么以「坐忘」为名-却分为七篇" aria-label="Permalink to &quot;二、为什么以「坐忘」为名，却分为七篇&quot;">​</a></h2><p>「坐忘」既是全书的中心方法，也是七个阶段共同指向的最终状态。</p><p>「坐」不只是身体静坐，主要是：心有所安；不再向外驰逐；不因境界而迁移；动静之中皆不失其根本。</p><p>「忘」也不是失忆或昏沉，而是：忘却对形体的执著；忘却名利得失；忘却分别计较；忘却「我正在修道」的自我意识；最终连能忘之心、所忘之物也不执著。</p><p>因此七篇不是七套平行的功法，而是逐层解除坐忘障碍的过程：</p><table tabindex="0"><thead><tr><th>篇章</th><th>所要解决的问题</th></tr></thead><tbody><tr><td>敬信</td><td>对道犹疑不决，不能真正实行</td></tr><tr><td>断缘</td><td>外在交往和俗务不断牵心</td></tr><tr><td>收心</td><td>心随境转，杂念不断，不能自主</td></tr><tr><td>简事</td><td>事务太多，不知必要与非必要</td></tr><tr><td>真观</td><td>虽然暂得安静，却未能看破欲望与境界</td></tr><tr><td>泰定</td><td>定力未纯，智慧一生又容易向外炫用</td></tr><tr><td>得道</td><td>形神尚未完全与道冥合</td></tr></tbody></table><p>全书真正的修炼对象，不是外面的神秘力量，而是人的<strong>心与境、动与静、定与慧、形与神</strong>之间的关系。</p><h2 id="三、七篇的整体逻辑" tabindex="-1">三、七篇的整体逻辑 <a class="header-anchor" href="#三、七篇的整体逻辑" aria-label="Permalink to &quot;三、七篇的整体逻辑&quot;">​</a></h2><h3 id="_1-敬信-先解决「为什么要修」" tabindex="-1">1. 敬信：先解决「为什么要修」 <a class="header-anchor" href="#_1-敬信-先解决「为什么要修」" aria-label="Permalink to &quot;1. 敬信：先解决「为什么要修」&quot;">​</a></h3><p>修行的第一步不是技巧，而是方向。若只是好奇，却不真正相信坐忘是修道要门，一遇困难便会放弃；若一边向道，一边仍把名利、声色与世俗评价视为根本，也无法持续。</p><blockquote><p>信者道之根，敬者德之蒂。根深则道可长，蒂固则德可茂。</p></blockquote><p>但「敬信」不是盲信。它意味着：认可修道的价值；对方法保持尊重；决定亲自实行；再由实践验证所信。所以本篇最后仍落在「勤行」上，而不止于思想认同。</p><h3 id="_2-断缘-先停止制造新的牵累" tabindex="-1">2. 断缘：先停止制造新的牵累 <a class="header-anchor" href="#_2-断缘-先停止制造新的牵累" aria-label="Permalink to &quot;2. 断缘：先停止制造新的牵累&quot;">​</a></h3><p>「缘」是能牵引心神、使心不断向外活动的关系，包括：为显露才能而参与事务；为获得保护、提拔而经营关系；借庆贺吊唁维持人情往来；表面隐逸，内心却期待名位；以酒食交际换取未来利益。</p><p>因此「断缘」主要断的不是人与人之间一切正常关系，而是：</p><blockquote><p><strong>由机心、名利、交换和攀附所构成的牵缠。</strong></p></blockquote><p>对于不能废除的必要事务，本篇并不要求逃避：</p><blockquote><p>不得已而行之，勿遂生爱，系心为业。</p></blockquote><p>事情可以做，但不要使它成为新的心理依附。</p><h3 id="_3-收心-从外驰转为自主" tabindex="-1">3. 收心：从外驰转为自主 <a class="header-anchor" href="#_3-收心-从外驰转为自主" aria-label="Permalink to &quot;3. 收心：从外驰转为自主&quot;">​</a></h3><p>这是全书最长、也最核心的一篇。</p><blockquote><p>夫心者，一身之主，百神之帅。静则生慧，动则成昏。</p></blockquote><p>收心的基本方向：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心原本以道为根</span></span>
<span class="line"><span>  ↓ 因长期逐物而受染</span></span>
<span class="line"><span>  ↓ 习惯依附外境，失去自主</span></span>
<span class="line"><span>收心离境，不著一物</span></span>
<span class="line"><span>  ↓ 净除心垢，重见本性</span></span>
<span class="line"><span>归根 → 静定 → 复命 → 知常</span></span></code></pre></div><p>本篇同时反对几种错误：不是把一切念头全部消灭；不是让心任意浮游；不是执著于「空」；不是进入昏沉的「盲定」；不是一边广行俗事，一边宣称自己毫无染著；也不是强迫自己在短时间内完全无念。</p><p>它提出的核心原则是：</p><blockquote><p><strong>息乱而不灭照，守静而不著空。</strong></p></blockquote><p>停止杂乱的攀缘，但保留清醒的觉照；安住于静，却不把「静」或「空」当作可执著的对象。</p><h3 id="_4-简事-重整现实生活" tabindex="-1">4. 简事：重整现实生活 <a class="header-anchor" href="#_4-简事-重整现实生活" aria-label="Permalink to &quot;4. 简事：重整现实生活&quot;">​</a></h3><p>「断缘」之后仍有许多生活事务不能废除，所以还要「简事」。简事不是拒绝一切行动，而是分辨：哪些是维持生命所必需的；哪些只是欲望的附加品；哪些属于自己的责任；哪些超出了自己的能力和分际。</p><blockquote><p>知生之有分，不务分之所无；识事之有当，不任非当之事。</p></blockquote><p>简事的目的，是为收心与定慧保存条件。若事务过多，便会 <strong>心劳 → 智昏 → 形神疲弊 → 修道中断</strong>。所以它是对生活结构的实际整理，不只是内在观念。</p><h3 id="_5-真观-以智慧松开执著" tabindex="-1">5. 真观：以智慧松开执著 <a class="header-anchor" href="#_5-真观-以智慧松开执著" aria-label="Permalink to &quot;5. 真观：以智慧松开执著&quot;">​</a></h3><p>仅仅减少事务、暂时安静，还不等于真正解除烦恼。许多欲望和恐惧已变成内在习惯，即使外境暂时消失，它们仍会反复生起。因此需要「真观」。</p><p>真观不是预测未来的神秘能力，而是：观察事物的根本；从原因看见后果；在祸福尚未完全形成时辨别趋势；看见欲望、贫病、生死和毁誉怎样在心中成立。</p><p>本篇主要观察五类问题：衣食与必要事务；色欲；对他人善恶的执著；贫困、疾病与逆境；身体、生死和爱恶。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收心：使心暂时不逐境</span></span>
<span class="line"><span>真观：看明白为什么不应逐境</span></span></code></pre></div><p>因此，收心主要成就「定」的基础，真观则逐渐生起「慧」。</p><h3 id="_6-泰定-定慧相养" tabindex="-1">6. 泰定：定慧相养 <a class="header-anchor" href="#_6-泰定-定慧相养" aria-label="Permalink to &quot;6. 泰定：定慧相养&quot;">​</a></h3><p>「泰定」不是勉强按住念头，而是安定已经成熟：</p><blockquote><p>无心于定，而无所不定。</p></blockquote><p>但本篇认为，智慧显现以后还有一个更隐微的危险：<strong>以智慧炫耀自己、纵意辩论、参与过多事务。</strong></p><blockquote><p>非生慧难，慧而不用难。</p></blockquote><p>真正的定慧关系不是「得定 → 生慧 → 到处使用智慧」，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以定生慧 → 以慧护定 → 有慧而不炫用 → 定慧交相涵养 → 成就道德</span></span></code></pre></div><p>「慧而不用」并非永远不处理事情，而是不以所知建立自我、追逐声名。</p><h3 id="_7-得道-由心及形-与道冥合" tabindex="-1">7. 得道：由心及形，与道冥合 <a class="header-anchor" href="#_7-得道-由心及形-与道冥合" aria-label="Permalink to &quot;7. 得道：由心及形，与道冥合&quot;">​</a></h3><p>前六篇说明修道的过程，第七篇描述其完成状态。在《坐忘论》的生命观中，得道不只是心理上有所领悟，还包括：心与道合；神与道合；形神合一；最终形体也受到道的转化。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道力较浅 → 只达到内心慧觉</span></span>
<span class="line"><span>道力深厚 → 道力兼及形体，形神俱妙</span></span></code></pre></div><p>阅读时需要同时把握两层：</p><ul><li><strong>修养层面</strong>：虚心、定慧、无执、含光藏辉——可作为心性论理解；</li><li><strong>宗教层面</strong>：形神转化、长生、神仙、即身成真——属于道教成仙论，不能直接转化为现代科学结论。</li></ul><h2 id="四、《坐忘枢翼》的地位" tabindex="-1">四、《坐忘枢翼》的地位 <a class="header-anchor" href="#四、《坐忘枢翼》的地位" aria-label="Permalink to &quot;四、《坐忘枢翼》的地位&quot;">​</a></h2><p>「枢」是门户转动的关键，「翼」有辅助、补充之意，可理解为对七篇枢要的补充说明。它把全书进一步归纳为「三戒」：一曰简缘，二曰无欲，三曰静心。</p><p>其中最重要的总诀是：</p><blockquote><p><strong>唯灭动心，不灭照心；但冥虚心，不冥有心；不依一物，而心常住。</strong></p></blockquote><p>大意是：止息攀缘躁动之心，但不消灭清醒觉照；使妄心寂静，却不是让意识陷入昏暗；不依附任何对象，心又能保持安住。这可以看作《坐忘论》对「坐忘不是昏沉」最明确的说明。</p><h2 id="五、主要思想来源" tabindex="-1">五、主要思想来源 <a class="header-anchor" href="#五、主要思想来源" aria-label="Permalink to &quot;五、主要思想来源&quot;">​</a></h2><p>《坐忘论》并非只据一部经典写成。它以《老子》《庄子》为主要骨架，同时吸收《西升经》《生神经》等道教经典，也明显受唐代佛教止观、空性、戒欲与业报思想的影响。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《老子》 清静、无欲、归根、复命、知常、无为 → 根本方向</span></span>
<span class="line"><span>《庄子》 坐忘、心斋、忘形、泰定、凝神、养生 → 境界与心理技术</span></span>
<span class="line"><span>道教经书《西升经》《生神经》等 形神合同、守一、长生 → 成仙论</span></span>
<span class="line"><span>佛教思想 止观、空性、戒欲、业报、定慧 → 观心与真观结构</span></span></code></pre></div><p>司马承祯并非简单拼接诸家概念，而是把这些材料重新组织成一条道教修道次第。他的写作方式有两个来源：一是<strong>经旨</strong>（恭寻经典根本意旨），二是<strong>与心法相应</strong>（只取能落实到观心、收心的部分）。因此本书不是经文汇编，而是「经典依据 + 修心经验 + 次第组织」。</p><p>其中「穷则变，变则通，通则久」一路（《易传》）也渗入全书：生命走入困局 → 审察旧有方向 → 转变习惯 → 恢复通达。逐条引文与原典语境见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h2 id="六、全书路线图" tabindex="-1">六、全书路线图 <a class="header-anchor" href="#六、全书路线图" aria-label="Permalink to &quot;六、全书路线图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人贵其生，却又贪爱促成生死烦恼之业</span></span>
<span class="line"><span>        ↓ 认识这种生活方向的倒置</span></span>
<span class="line"><span>敬信：相信大道与坐忘，决定实际修习</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>断缘：不再主动经营名利、机心和俗务之缘</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>收心：收心离境，不著一物；息乱而不灭照，守静而不著空</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>简事：分辨必要与非必要、分内与分外，保存形神</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>真观：观欲望、贫病、善恶、生死之本，从认识上松开爱恶</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>泰定：无心于定而无所不定；本性发慧，定慧交养</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>得道：含光藏辉，不以智慧向外耗神；形神合同，与道冥一</span></span></code></pre></div><p>四条主线贯穿其中：</p><ol><li><strong>由外到内</strong>：断缘、简事 → 收心、真观</li><li><strong>由有为到无为</strong>：作意收心 → 无心于定</li><li><strong>由定到慧，再由慧护定</strong>：收心生定、真观生慧、泰定交养、得道不执定慧之名</li><li><strong>由心及形</strong>：先安其心，再凝其神，终而形神与道冥一</li></ol><p>最后一条，是《坐忘论》区别于一般心理调节著作的地方。</p><h2 id="七、阅读时特别警惕的几种误读" tabindex="-1">七、阅读时特别警惕的几种误读 <a class="header-anchor" href="#七、阅读时特别警惕的几种误读" aria-label="Permalink to &quot;七、阅读时特别警惕的几种误读&quot;">​</a></h2><ol><li><strong>坐忘不是昏沉</strong>——全书强调「不灭照心」；若觉知完全断绝，只是「盲定」。</li><li><strong>断缘不是逃避一切责任</strong>——不可废之事仍应「不得已而行之」，只是不要因此生爱著。</li><li><strong>简事不是消极无能</strong>——它要求识别轻重、分内与分外，使智力与形神不被无谓事务耗尽。</li><li><strong>无欲不是仇视身体</strong>——原文有严厉的戒欲语言，应放在唐代出家修道语境中理解，不能转化为身体羞耻或对正常情感的敌视。</li><li><strong>不动不是压抑</strong>——束心太急，原文明确说可能「成病」；真正的尺度是「制而无著，放而不逸」。</li><li><strong>慧不是能言善辩</strong>——少得智慧便多言多辩，会使心神重新外驰。</li><li><strong>神异景象不是得道证明</strong>——《枢翼》把定中出现的真人、老君、神异诡怪列入需要警惕的境相。真正的判断标准不在「看见什么」，而在烦恼是否减少、心是否更安定、是否不造新业。</li><li><strong>神仙境界不能全部心理化</strong>——《得道》与《枢翼》确实包含长生、炼形与神仙阶位；应承认其宗教含义，不能为迁就现代观念而全部解释成普通心理健康。</li></ol><h2 id="八、与《天隐子》的对应与差异" tabindex="-1">八、与《天隐子》的对应与差异 <a class="header-anchor" href="#八、与《天隐子》的对应与差异" aria-label="Permalink to &quot;八、与《天隐子》的对应与差异&quot;">​</a></h2><h3 id="逐篇对应" tabindex="-1">逐篇对应 <a class="header-anchor" href="#逐篇对应" aria-label="Permalink to &quot;逐篇对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《天隐子》</th><th>《坐忘论》</th><th>对应关系</th></tr></thead><tbody><tr><td>神仙第一</td><td>总论、得道</td><td>人本具灵气，通过修养复归于道</td></tr><tr><td>易简第二</td><td>收心后半、枢翼</td><td>法贵能行，不贵玄谈；方法须简要直接</td></tr><tr><td>渐门第三</td><td>七篇整体</td><td>都主张由浅入深，不可跳过基础</td></tr><tr><td>斋戒第四</td><td>断缘、简事</td><td>减少身体和生活上的多余负担</td></tr><tr><td>安处第五</td><td>断缘、收心</td><td>先减少外扰，才能安顿心神</td></tr><tr><td>存想第六</td><td>收心、真观</td><td>心目返照，不再终日逐外</td></tr><tr><td>坐忘第七</td><td>泰定、枢翼</td><td>心不动、形我淡化，觉照却不灭</td></tr><tr><td>神解第八</td><td>得道</td><td>定慧贯通，形神与道冥合</td></tr></tbody></table><h3 id="关键概念的深化" tabindex="-1">关键概念的深化 <a class="header-anchor" href="#关键概念的深化" aria-label="Permalink to &quot;关键概念的深化&quot;">​</a></h3><ul><li><strong>「存想」与「收心」</strong>：《天隐子》的「存谓存我之神，想谓想我之身」提出返照方向，《坐忘论》的「收心」说明具体心理机制——收心离境、住无所有、不著一物、随起随制、行住坐卧都要安养此心。</li><li><strong>「因存想而忘」与「不依一物」</strong>：初步必须有意识地收心；收心纯熟以后，不能再执著于方法；心无所依，却不是昏散。</li><li><strong>「心不动」与「真定」</strong>：《坐忘论》把一句「心不动」扩展成完整的调心理论——不动不是没有觉知、不是强力压制、不是只在静室中成立。</li><li><strong>「形都泯」与「形如槁木」</strong>：都不是身体真的消失，而是身体不再成为执著中心、「我正在修行」的意识淡化。</li><li><strong>「神解」与「泰定—得道」</strong>：《坐忘论》的泰定与得道，可以看作对《天隐子·神解》的详细阐述。</li><li><strong>两条起点的呼应</strong>：《天隐子》说人本有灵气（有而不自知），《坐忘论》说「人之有道，若鱼之有水」——道理是人的生命根本，修道是<strong>恢复</strong>而非制造。</li></ul><h3 id="不能强行等同之处" tabindex="-1">不能强行等同之处 <a class="header-anchor" href="#不能强行等同之处" aria-label="Permalink to &quot;不能强行等同之处&quot;">​</a></h3><ol><li><strong>次第不同</strong>：五渐（斋戒—安处—存想—坐忘—神解）与七阶（敬信—断缘—收心—简事—真观—泰定—得道）不是简单拆分，而是重新构造了修行逻辑。</li><li><strong>《坐忘论》更重「真观」</strong>：在收心与泰定之间增加「简事」与「真观」，说明只靠停止杂念还不够，还要从智慧上解除欲望与错误认识。</li><li><strong>戒欲色彩更强</strong>：《真观》对色欲、生死、贫病、业报有大量论述，比《天隐子》更严厉，也更接近唐代道佛修行共同的出离传统。</li><li><strong>成仙论更完整</strong>：《得道》与《枢翼》进一步提出真人、神人、至人、炼形为气、炼气成神、炼神合道，构成一套更完整的形神转化论。</li></ol><h2 id="九、现实启示-检查「目标—手段倒置」" tabindex="-1">九、现实启示：检查「目标—手段倒置」 <a class="header-anchor" href="#九、现实启示-检查「目标—手段倒置」" aria-label="Permalink to &quot;九、现实启示：检查「目标—手段倒置」&quot;">​</a></h2><p>开篇总论最适合当一面镜子，用来检查生活中那些现代形式的「恶其苦，而爱其业」：</p><ul><li>为了生活得更好，长期透支健康；</li><li>为了获得自由，承担越来越多放不下的事务；</li><li>为了心安，不断购买更多东西；</li><li>为了修行进步，焦虑地比较境界；</li><li>为了得到认可，谈论许多道理，却不愿改变习惯。</li></ul><p>总论并不要求立刻抛弃现有生活，而是先诚实地观察：</p><ol><li>我口头上最珍惜什么？</li><li>我的时间实际上都投入了什么？</li><li>哪些行为正在制造我所厌恶的结果？</li><li>哪些「努力」只是使错误方向走得更快？</li><li>哪些事情是在养生，哪些事情是在耗生？</li><li>我重视的是修道之名，还是可实行的改变？</li></ol><p>这正是「审惟倒置」的现代意义——修道的第一步，是辨认并扭转那些一面求生、一面伤生，一面求道、一面背道的生活方向。</p><h2 id="十、逐章整理的方式" tabindex="-1">十、逐章整理的方式 <a class="header-anchor" href="#十、逐章整理的方式" aria-label="Permalink to &quot;十、逐章整理的方式&quot;">​</a></h2><p>各篇按同一结构展开：原文分段 → 白话串讲 → 关键字词 → 论证结构 → 引经据典及原典语境 → 与《天隐子》的对应 → 容易误解之处 → 现实修养上的启示 → 小结。</p><p>《收心》《真观》两篇较长，按内部层次拆成数段，避免一次处理过多反而看不清结构。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《坐忘论》，唐·司马承祯撰。</li><li>《庄子·大宗师》（「坐忘」出处）、《道德经》、《西升经》、《生神经》等。</li><li>相关篇目：<a href="/Dao/daoism/daoist-classics/tianyinzi">《天隐子》</a>、<a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a>。</li></ul>`,97)])])}const u=t(l,[["render",i]]);export{g as __pageData,u as default};
